<style>
.bf-page{width:100%;color:var(--text-primary)}.bf-page .mpc-card,.bf-page .mpc-menu{background:var(--bg-card);border:1px solid var(--border-glass);border-radius:20px}.bf-page .mpc-title,.bf-page .mpc-kpi,.bf-page .mpc-text{color:var(--text-primary)}.bf-page .mpc-sub,.bf-page .mpc-faint,.bf-page .mpc-th{color:var(--text-muted)}.bf-page .mpc-td{color:var(--text-primary)}.bf-page .mpc-input{background-color:var(--bg-glass-input);color:var(--text-primary);border-color:var(--border-glass);border-radius:12px;padding:10px 12px;font-size:13px}.bf-page .mpc-step{border-radius:12px;color:var(--text-muted);background:var(--bg-card);border-color:var(--border-glass);padding:11px 18px}html .bf-page .mpc-step.active{background:#3454ef;color:white;border-color:#3454ef;box-shadow:none}.bf-page .mpc-step-num,.bf-page .mpc-step-sep{display:none}.bf-workspace{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start}.bf-preview{position:sticky;top:90px}.bf-preview strong{font-size:24px;display:block;margin:8px 0}.bf-bar{height:7px;border-radius:8px;background:#3454ef;margin:8px 0}.bf-levels{display:flex;gap:8px;margin:16px 0;flex-wrap:wrap}.bf-levels button{padding:8px 14px;border:1px solid var(--border-glass);border-radius:10px}.bf-levels button[aria-selected=true]{background:#3454ef;color:white}.bf-page summary{cursor:pointer;font-weight:600}.bf-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:15px}.bf-page .bk-stat-grid{margin-bottom:24px}.bf-page .bk-stat-grid strong{font-size:36px!important}.bf-page .bk-stat-grid .ov-count{min-height:165px}.bf-page .bk-stat-grid .ov-count-label{font-size:14px}.bf-badge{display:inline-block;border:1px solid var(--border-glass);border-radius:999px;font-size:11px;padding:4px 9px;color:var(--text-muted)}.bf-page .mpc-export-btn{color:var(--text-primary);background:var(--bg-card);border-color:var(--border-glass)}@media(max-width:1100px){.bf-workspace{grid-template-columns:1fr}.bf-preview{position:static}}@media(prefers-reduced-motion:reduce){.bf-page *{animation:none!important;transition:none!important}}
